    function js_searchData() {
        var _search = $('#txtSearchBox').val()
        if (_search == "" || _search == null || _search == undefined) {
            alert("Please fill the Search Box ");
            return false;
        }
        else {
            $.ajax({
                type: 'POST',
                url: '/WebCMS/SearchDataShow',
                data: { Param: _search },
                async: false,
                dataType: 'json',
                success: function (data) {
                    var _Html='';
                    if (data.length > 0) {
                        for (var P = 0; P < data.length; P++) {

                            _Html += '<tr>
<td>' + data[P].PageName + '</td>';
                            if (data[P].AddBy == 0) {
                                _Html += '<td>
<a href="' + data[P].PageId + '" title="Read more - ' + data[P].PageName + '"  target="_blank" rel="noopener noreferrer">
<i class="fa fa-eye">
</i>
</a>
</td>';
                            }
                            else if (data[P].AddBy == 1) {
                                _Html += '<td>
<a href="../Website/' + data[P].MetaDescription +'/CONTENTFILES/' + data[P].HtmlContent + '" target="_blank" rel="noopener noreferrer" title="Read more - ' + data[P].PageName + '">
<i class="fa fa-eye">
</i>
</a>
</td>';
                            }

                            _Html += '</tr>';
                        }
                        $('#ResultSearchData').html(_Html);
                        $('#SearchResults').modal('show');
